/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_order_items_inventory` BEFORE INSERT ON `order_items` FOR EACH ROW BEGIN
    IF NEW.warehouse_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Indique la bodega de salida.';
    END IF;

    UPDATE inventory
    SET quantity_on_hand = quantity_on_hand - NEW.quantity
    WHERE warehouse_id = NEW.warehouse_id
      AND product_id = NEW.product_id
      AND NEW.quantity > 0
      AND quantity_on_hand - quantity_reserved >= NEW.quantity;

    IF ROW_COUNT() = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cantidad invalida o inventario insuficiente en la bodega.';
    END IF;
END */;;
DELIMITER ;
