/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_orders_status_audit` AFTER UPDATE ON `orders` FOR EACH ROW INSERT INTO order_status_history
    (order_id, old_status, new_status, changed_by)
SELECT NEW.order_id, OLD.status, NEW.status, USER()
WHERE OLD.status <> NEW.status */;;
